(function(){'use strict';var cfg=window.goProduct||{};var keys={follows:'go-follows-v1',saved:'go-saved-v1',reading:'go-continue-v1',a11y:'go-a11y-v1'};function read(key,fallback){try{var value=JSON.parse(localStorage.getItem(key));return value===null?fallback:value;}catch(e){return fallback;}}
function write(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch(e){}}
function unique(list){return Array.from(new Set((list||[]).map(String)));}
function esc(value){var d=document.createElement('div');d.textContent=value||'';return d.innerHTML;}
function fetchJson(url,options){options=options||{};var publicRequest=!!options.publicRequest;delete options.publicRequest;var baseHeaders={'Content-Type':'application/json'};if(cfg.nonce&&!publicRequest)baseHeaders['X-WP-Nonce']=cfg.nonce;options.headers=Object.assign(baseHeaders,options.headers||{});options.credentials=options.credentials||'same-origin';return fetch(url,options).then(function(r){return r.text().then(function(text){var body={};try{body=text?JSON.parse(text):{};}catch(e){body={message:text||'Falha na solicitação.'};}
if(!r.ok){var error=new Error(body.message||'Falha na solicitação.');error.status=r.status;throw error;}
return body;});});}
function readerId(){var key='go-reader-id-v1';try{var existing=localStorage.getItem(key);if(existing&&/^[A-Za-z0-9_-]{20,96}$/.test(existing))return existing;var next='';if(window.crypto&&typeof window.crypto.randomUUID==='function'){next=window.crypto.randomUUID().replace(/-/g,'');}else if(window.crypto&&typeof window.crypto.getRandomValues==='function'){var bytes=new Uint8Array(24);window.crypto.getRandomValues(bytes);next=Array.prototype.map.call(bytes,function(b){return('0'+b.toString(16)).slice(-2);}).join('');}else{next=String(Date.now())+Math.random().toString(36).slice(2)+Math.random().toString(36).slice(2);}
localStorage.setItem(key,next);return next;}catch(e){return'fallback'+String(Date.now())+Math.random().toString(36).slice(2);}}
function followDialog(){var existing=document.querySelector('[data-go-follow-dialog]');if(existing)return existing;var dialog=document.createElement('dialog');dialog.className='go-follow-dialog';dialog.setAttribute('data-go-follow-dialog','');dialog.innerHTML='<div class="go-follow-dialog__inner">'+
'<span class="go-follow-dialog__eyebrow">Preferências do leitor</span>'+
'<h2 data-go-follow-dialog-title></h2>'+
'<p data-go-follow-dialog-copy></p>'+
'<p class="go-follow-dialog__note" data-go-follow-dialog-note></p>'+
'<div class="go-follow-dialog__actions"><button type="button" class="go-follow-dialog__close" data-go-follow-dialog-close>Entendi</button></div>'+
'</div>';document.body.appendChild(dialog);var close=dialog.querySelector('[data-go-follow-dialog-close]');if(close)close.addEventListener('click',function(){if(dialog.close)dialog.close();else dialog.removeAttribute('open');});dialog.addEventListener('click',function(event){if(event.target===dialog){if(dialog.close)dialog.close();else dialog.removeAttribute('open');}});return dialog;}
function showFollowMeaning(button,following){var dialog=followDialog();var name=String(button.dataset.followName||'').trim()||'este assunto';var title=dialog.querySelector('[data-go-follow-dialog-title]');var copy=dialog.querySelector('[data-go-follow-dialog-copy]');var note=dialog.querySelector('[data-go-follow-dialog-note]');if(following){title.textContent='Agora você segue '+name;copy.textContent='Isso sinaliza ao Overdrive que você quer encontrar com mais facilidade novas matérias relacionadas a '+name+'. Esse interesse pode ser usado para organizar recomendações e a área Para Você.';note.textContent='Seguir não cria uma conta, não ativa notificações e pode ser desfeito a qualquer momento pelo mesmo botão.';}else{title.textContent='Você deixou de seguir '+name;copy.textContent='O assunto deixa de ser considerado entre os interesses salvos neste navegador para recomendações personalizadas.';note.textContent='As matérias continuam disponíveis normalmente e você pode voltar a seguir quando quiser.';}
if(typeof dialog.showModal==='function'){if(!dialog.open)dialog.showModal();}else{dialog.setAttribute('open','');}}
function initFollowButtons(){var follows=read(keys.follows,[]);var visitor=readerId();if(cfg.rest&&follows.length&&!read('go-follow-batch-sync-v47',false)){fetchJson(cfg.rest+'follows/sync',{method:'POST',body:JSON.stringify({visitor:visitor,tokens:follows.slice(0,60)})}).then(function(){write('go-follow-batch-sync-v47',true);}).catch(function(){});}
document.querySelectorAll('[data-go-follow]').forEach(function(button){var id=String(button.dataset.objectId||''),type=button.dataset.objectType||'';var token=type+':'+id;var alias=String(button.dataset.followAlias||'');if(alias&&follows.indexOf(alias)!==-1&&follows.indexOf(token)===-1){follows=follows.filter(function(item){return item!==alias;});follows.unshift(token);follows=unique(follows).slice(0,60);write(keys.follows,follows);}
function paint(){var active=follows.indexOf(token)!==-1;button.setAttribute('aria-pressed',active?'true':'false');var label=button.querySelector('[data-go-follow-label]');var defaultLabel=button.dataset.followDefaultLabel||(type==='games'?'Seguir jogo':(type==='productions'?'Seguir produção':'Seguir assunto'));if(label)label.textContent=active?'Seguindo':defaultLabel;}
paint();button.addEventListener('click',function(){follows=read(keys.follows,[]);var index=follows.indexOf(token);var following=index===-1;if(following)follows.unshift(token);else follows.splice(index,1);follows=unique(follows).slice(0,60);write(keys.follows,follows);paint();showFollowMeaning(button,following);if(!cfg.rest||!id||!type)return;fetchJson(cfg.rest+'follows',{method:'POST',body:JSON.stringify({id:Number(id),type:type,visitor:visitor,following:following})}).then(function(body){}).catch(function(){});});});}
function initSaveButtons(){var saved=read(keys.saved,[]);document.querySelectorAll('[data-go-save]').forEach(function(button){var id=String(button.dataset.postId||'');function paint(){var active=saved.indexOf(id)!==-1;button.setAttribute('aria-pressed',active?'true':'false');var label=button.querySelector('[data-go-save-label]');if(label)label.textContent=active?'Salvo':'Salvar';}
paint();button.addEventListener('click',function(){saved=read(keys.saved,[]);var index=saved.indexOf(id);if(index===-1)saved.unshift(id);else saved.splice(index,1);saved=unique(saved).slice(0,100);write(keys.saved,saved);paint();});});}
function trackContinueReading(){if(!cfg.isSinglePost||!cfg.current||!cfg.current.id)return;var entry=Object.assign({},cfg.current,{updated:Date.now(),progress:0});var measureTimer=0;var persistScheduled=false;var dirty=false;function measure(){var max=Math.max(1,document.documentElement.scrollHeight-window.innerHeight);entry.progress=Math.min(100,Math.max(0,Math.round((window.scrollY/max)*100)));entry.updated=Date.now();dirty=true;}
function persist(){persistScheduled=false;if(!dirty)return;var list=read(keys.reading,[]).filter(function(item){return String(item.id)!==String(entry.id);});list.unshift(entry);write(keys.reading,list.slice(0,20));dirty=false;}
function schedulePersist(){if(persistScheduled)return;persistScheduled=true;if('requestIdleCallback'in window){window.requestIdleCallback(persist,{timeout:1800});}else{window.setTimeout(persist,900);}}
function scheduleMeasure(){if(measureTimer)return;measureTimer=window.setTimeout(function(){measureTimer=0;measure();schedulePersist();},250);}
measure();schedulePersist();window.addEventListener('scroll',scheduleMeasure,{passive:true});window.addEventListener('pagehide',function(){if(measureTimer){window.clearTimeout(measureTimer);measureTimer=0;}
measure();persist();});}
function renderCards(container,items,emptyText,showProgress){if(!container)return;if(!items||!items.length){container.innerHTML='<p class="go-product-empty">'+esc(emptyText||'Nada por aqui ainda.')+'</p>';return;}
container.innerHTML='<div class="go-product-card-grid">'+items.map(function(item){var image=item.image?'<img src="'+esc(item.image)+'" alt="" width="640" height="360" loading="lazy" decoding="async">':'';var progress=showProgress&&item.progress?'<span class="go-reading-progress"><i style="width:'+Math.min(100,Math.max(0,item.progress))+'%"></i></span>':'';return'<article class="go-product-card"><a class="go-product-card__media" tabindex="-1" aria-hidden="true" href="'+esc(item.url)+'">'+image+'</a><div><h3><a href="'+esc(item.url)+'">'+esc(item.title)+'</a></h3>'+(item.excerpt?'<p>'+esc(item.excerpt)+'</p>':'')+progress+'</div></article>';}).join('')+'</div>';}
function hydrateSavedPage(){var container=document.querySelector('[data-go-saved-list]');if(!container)return;var ids=read(keys.saved,[]);if(!ids.length)return renderCards(container,[],'Você ainda não salvou nenhuma matéria.');fetchJson((cfg.rest||'')+'content-cards?ids='+encodeURIComponent(ids.join(','))).then(function(items){renderCards(container,items,'Você ainda não salvou nenhuma matéria.');}).catch(function(){renderCards(container,[],'Não foi possível carregar seus itens salvos.');});}
function hydrateHomeContinue(){var section=document.querySelector('[data-go-home-continue]'),container=document.querySelector('[data-go-home-continue-list]');if(!section||!container)return;var items=read(keys.reading,[]).slice(0,4);if(!items.length)return;section.hidden=false;renderCards(container,items,'',true);}
function hydrateForYouPage(){var feed=document.querySelector('[data-go-personalized-feed]');var reading=document.querySelector('[data-go-continue-list]');if(reading)renderCards(reading,read(keys.reading,[]),'As matérias que você começar a ler aparecerão aqui.',true);if(!feed)return;var follows=read(keys.follows,[]),gameIds=[],productionIds=[],entityIds=[],tagIds=[],categoryIds=[],serviceIds=[],platformIds=[];follows.forEach(function(token){var parts=token.split(':'),id=parseInt(parts[1],10);if(!id)return;if(parts[0]==='games')gameIds.push(id);if(parts[0]==='productions')productionIds.push(id);if(parts[0]==='go_entity')entityIds.push(id);if(parts[0]==='post_tag')tagIds.push(id);if(parts[0]==='category')categoryIds.push(id);if(parts[0]==='go_service')serviceIds.push(id);if(parts[0]==='go_platform')platformIds.push(id);});if(!gameIds.length&&!productionIds.length&&!entityIds.length&&!tagIds.length&&!categoryIds.length&&!serviceIds.length&&!platformIds.length)return renderCards(feed,[],'Siga assuntos para montar esta área.');fetchJson((cfg.rest||'')+'personalized-feed',{method:'POST',body:JSON.stringify({game_ids:gameIds,production_ids:productionIds,entity_ids:entityIds,tag_ids:tagIds,category_ids:categoryIds,service_ids:serviceIds,platform_ids:platformIds})}).then(function(items){renderCards(feed,items,'Ainda não há novas matérias para os assuntos seguidos.');}).catch(function(){renderCards(feed,[],'Não foi possível carregar sua seleção agora.');});}
function initPopularityTracking(){var meta=document.querySelector('meta[name="go-track-post"]');if(!meta||!cfg.productRest)return;var id=meta.content,now=new Date();var day=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');var dedupe=read('go-view-dedupe-v1',{});if(dedupe[id]===day)return;window.setTimeout(function(){var body=JSON.stringify({post_id:parseInt(id,10)});function markTracked(){dedupe[id]=day;write('go-view-dedupe-v1',dedupe);}
function sendView(){return fetchJson(cfg.productRest+'track-view',{method:'POST',keepalive:true,publicRequest:true,body:body});}
sendView().then(markTracked).catch(function(error){if(!cfg.rest||!error||(error.status!==401&&error.status!==403))return;fetchJson(cfg.rest+'rest-nonce?ts='+Date.now(),{method:'POST',publicRequest:true,cache:'no-store'}).then(function(fresh){if(!fresh||!fresh.nonce)throw error;cfg.nonce=fresh.nonce;return sendView();}).then(markTracked).catch(function(){});});},5000);}
function initPriceAlerts(){document.querySelectorAll('[data-go-price-alert]').forEach(function(box){var form=box.querySelector('form'),status=box.querySelector('[data-go-price-alert-status]');if(!form||!cfg.productRest)return;var setStatus=function(msg){if(status)status.textContent=msg;};form.addEventListener('submit',function(event){event.preventDefault();var data=new FormData(form);setStatus('Criando alerta…');fetchJson(cfg.productRest+'price-alert',{method:'POST',body:JSON.stringify({game_id:parseInt(box.dataset.gameId,10),email:data.get('email'),target_price:data.get('target_price'),consent:data.get('consent')==='1'})}).then(function(r){setStatus(r.message||'Alerta criado.');form.reset();}).catch(function(e){setStatus(e&&e.message?e.message:'Não foi possível criar o alerta.');});});});}
function initNewsletterPreferences(){var form=document.querySelector('[data-go-newsletter-preferences]');if(!form||!cfg.productRest)return;var status=form.querySelector('[data-go-preferences-status]');var button=form.querySelector('button[type="submit"]');var buttonLabel=form.querySelector('[data-go-preferences-submit-label]');var defaultLabel=buttonLabel?buttonLabel.textContent:'Salvar preferências';function setState(type,message){if(!status)return;status.classList.remove('is-success','is-error','is-loading');if(type)status.classList.add('is-'+type);status.textContent=message||'';}
function setLoading(loading){if(!button)return;button.disabled=loading;button.classList.toggle('is-loading',loading);button.setAttribute('aria-busy',loading?'true':'false');if(buttonLabel)buttonLabel.textContent=loading?'Salvando…':defaultLabel;}
form.addEventListener('input',function(){if(status&&!status.classList.contains('is-loading'))setState('','');});form.addEventListener('submit',function(event){event.preventDefault();if(!form.reportValidity())return;var data=new FormData(form),segments=[];form.querySelectorAll('input[name="segments[]"]:checked').forEach(function(input){segments.push(input.value);});setLoading(true);setState('loading','Registrando suas escolhas…');fetchJson(cfg.productRest+'newsletter-preferences',{method:'POST',body:JSON.stringify({email:data.get('email'),segments:segments,consent:data.get('consent')==='1'})}).then(function(r){setState('success',r.message||'Preferências salvas com sucesso.');}).catch(function(e){setState('error',e&&e.message?e.message:'Não foi possível salvar agora. Tente novamente.');}).finally(function(){setLoading(false);});});}
function initLaunchFilters(){var toolbar=document.querySelector('[data-go-launch-filters]');if(!toolbar)return;var items=Array.prototype.slice.call(document.querySelectorAll('[data-go-launch-item]'));toolbar.addEventListener('click',function(event){var button=event.target.closest('button[data-platform]');if(!button)return;var platform=button.dataset.platform;toolbar.querySelectorAll('button').forEach(function(b){b.classList.toggle('go-btn--mint',b===button);});items.forEach(function(item){item.hidden=platform!=='all'&&(item.dataset.platforms||'').split(/\s+/).indexOf(platform)===-1;});document.querySelectorAll('.go-launch-month').forEach(function(month){month.hidden=!month.querySelector('[data-go-launch-item]:not([hidden])');});});}
function initA11y(){var root=document.querySelector('[data-go-a11y]');if(!root)return;var toggle=root.querySelector('[data-go-a11y-toggle]'),panel=root.querySelector('.go-a11y__panel'),closeButton=root.querySelector('[data-go-a11y-close]');var fontDec=root.querySelector('[data-go-font-dec]'),fontInc=root.querySelector('[data-go-font-inc]');var readingButton=root.querySelector('[data-go-reading-mode]');var contrastDec=root.querySelector('[data-go-contrast-dec]'),contrastInc=root.querySelector('[data-go-contrast-inc]');var motionButton=root.querySelector('[data-go-reduce-motion]'),resetButton=root.querySelector('[data-go-a11y-reset]');var articleContext=root.getAttribute('data-go-a11y-context')==='article';var defaults={scale:1,reading:false,motion:false,contrast:0};var state=Object.assign({},defaults,read(keys.a11y,defaults));var status=root.querySelector('[data-go-a11y-status]');function announce(message){if(!status)return;status.textContent='';window.setTimeout(function(){status.textContent=message;},20);}
function pressed(button,value){if(button)button.setAttribute('aria-pressed',value?'true':'false');}
function apply(message){state.scale=Math.max(0.9,Math.min(1.3,Number(state.scale)||1));state.contrast=Math.max(-1,Math.min(1,parseInt(state.contrast,10)||0));if(articleContext){document.documentElement.setAttribute('data-go-font-scale',String(Math.round(state.scale*100)));}else{document.documentElement.removeAttribute('data-go-font-scale');}
document.body.classList.toggle('go-reading-mode',articleContext&&!!state.reading);document.body.classList.toggle('go-reduce-motion',!!state.motion);document.body.classList.toggle('go-contrast-high',state.contrast===1);document.body.classList.toggle('go-contrast-low',state.contrast===-1);pressed(readingButton,articleContext&&state.reading);pressed(motionButton,state.motion);pressed(contrastDec,state.contrast===-1);pressed(contrastInc,state.contrast===1);write(keys.a11y,state);if(message)announce(message);}
apply();function setPanelOpen(open,restoreFocus){if(!panel)return;panel.toggleAttribute('hidden',!open);if(toggle)toggle.setAttribute('aria-expanded',open?'true':'false');if(!open&&restoreFocus&&toggle){try{toggle.focus({preventScroll:true});}catch(e){toggle.focus();}}}function closePanel(event){if(event){event.preventDefault();event.stopPropagation();}setPanelOpen(false,true);}if(toggle&&panel)toggle.addEventListener('click',function(){setPanelOpen(panel.hasAttribute('hidden'),false);});if(closeButton&&panel){closeButton.addEventListener('click',closePanel);closeButton.addEventListener('pointerup',closePanel);}if(fontInc)fontInc.addEventListener('click',function(){state.scale=Math.min(1.3,+(state.scale+0.1).toFixed(1));apply('Tamanho do texto aumentado.');});if(fontDec)fontDec.addEventListener('click',function(){state.scale=Math.max(0.9,+(state.scale-0.1).toFixed(1));apply('Tamanho do texto reduzido.');});if(contrastInc)contrastInc.addEventListener('click',function(){state.contrast=Math.min(1,state.contrast+1);apply(state.contrast===1?'Contraste aumentado.':'Contraste padrão.');});if(contrastDec)contrastDec.addEventListener('click',function(){state.contrast=Math.max(-1,state.contrast-1);apply(state.contrast===-1?'Contraste reduzido.':'Contraste padrão.');});if(readingButton)readingButton.addEventListener('click',function(){state.reading=!state.reading;apply(state.reading?'Modo leitura ativado.':'Modo leitura desativado.');});if(motionButton)motionButton.addEventListener('click',function(){state.motion=!state.motion;apply(state.motion?'Movimento reduzido.':'Movimento padrão restaurado.');});if(resetButton)resetButton.addEventListener('click',function(){state=Object.assign({},defaults);apply('Preferências de acessibilidade resetadas.');});}
function bootProductFeatures(){var run=function(fn){try{fn();}catch(e){if(window.console&&window.console.warn){window.console.warn('[go-verge] init skipped:',e);}}};run(initFollowButtons);run(initSaveButtons);run(initA11y);var hydrate=function(){[trackContinueReading,hydrateSavedPage,hydrateHomeContinue,hydrateForYouPage,initPopularityTracking,initPriceAlerts,initNewsletterPreferences,initLaunchFilters].forEach(run);};if('requestIdleCallback'in window){window.requestIdleCallback(hydrate,{timeout:1400});}else{window.setTimeout(hydrate,450);}}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',bootProductFeatures,{once:true});}else{bootProductFeatures();}}());
